def load_app(self) -> Flask:
    """Loads the Flask app (if not yet loaded) and returns it.  Calling
    this multiple times will just result in the already loaded app to
    be returned.
    """
    if self._loaded_app is not None:
        return self._loaded_app
    app: Flask | None = None
    if self.create_app is not None:
        app = self.create_app()
    else:
        if self.app_import_path:
            path, name = (
                re.split(r":(?![\\/])", self.app_import_path, maxsplit=1) + [None]
            )[:2]
            import_name = prepare_import(path)
            app = locate_app(import_name, name)
        else:
            for path in ("wsgi.py", "app.py"):
                import_name = prepare_import(path)
                app = locate_app(import_name, None, raise_if_not_found=False)

                if app is not None:
                    break

    if app is None:
        raise NoAppException(
            "Could not locate a Flask application. Use the"
            " 'flask --app' option, 'FLASK_APP' environment"
            " variable, or a 'wsgi.py' or 'app.py' file in the"
            " current directory."
        )

    if self.set_debug_flag:
        # Update the app's debug flag through the descriptor so that
        # other values repopulate as well.
        app.debug = get_debug_flag()

    self._loaded_app = app
    return app

def celery_init_app(app: Flask) -> Celery:
    class FlaskTask(Task):
        def __call__(self, *args: object, **kwargs: object) -> object:
            with app.app_context():
                return self.run(*args, **kwargs)

    celery_app = Celery(app.name, task_cls=FlaskTask)
    celery_app.config_from_object(app.config["CELERY"])
    celery_app.set_default()
    app.extensions["celery"] = celery_app
    return celery_app

def test_url_with_method(self, app, req_ctx):
    from flask.views import MethodView

    class MyView(MethodView):
        def get(self, id=None):
            if id is None:
                return "List"
            return f"Get {id:d}"

        def post(self):
            return "Create"

    myview = MyView.as_view("myview")
    app.add_url_rule("/myview/", methods=["GET"], view_func=myview)
    app.add_url_rule("/myview/<int:id>", methods=["GET"], view_func=myview)
    app.add_url_rule("/myview/create", methods=["POST"], view_func=myview)

    assert flask.url_for("myview", _method="GET") == "/myview/"
    assert flask.url_for("myview", id=42, _method="GET") == "/myview/42"
    assert flask.url_for("myview", _method="POST") == "/myview/create"

